package com.huy.enterprise.risk;
import java.time.OffsetDateTime; import java.util.*; import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.*; import com.huy.enterprise.order.*; import com.huy.enterprise.product.*; import com.huy.enterprise.shipment.*; import com.huy.enterprise.supplier.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class RiskEventService{private final RiskEventRepository repository;private final SupplierRepository suppliers;private final ProductRepository products;private final PurchaseOrderRepository orders;private final ShipmentRepository shipments;public List<RiskEventResponse> all(){return repository.findAll().stream().map(RiskEventResponse::from).toList();}public RiskEventResponse one(UUID id){return RiskEventResponse.from(get(id));}@Transactional public RiskEventResponse create(CreateRiskEventRequest r){RiskEvent e=new RiskEvent();e.setStatus(r.status()==null?RiskEventStatus.OPEN:r.status());apply(e,r.title(),r.riskType(),r.impactLevel(),r.description(),r.detectedAt()==null?OffsetDateTime.now():r.detectedAt(),r.supplierId(),r.productId(),r.purchaseOrderId(),r.shipmentId());return RiskEventResponse.from(repository.save(e));}@Transactional public RiskEventResponse update(UUID id,UpdateRiskEventRequest r){RiskEvent e=get(id);apply(e,r.title(),r.riskType(),r.impactLevel(),r.description(),r.detectedAt(),r.supplierId(),r.productId(),r.purchaseOrderId(),r.shipmentId());return RiskEventResponse.from(repository.save(e));}@Transactional public RiskEventResponse status(UUID id,RiskEventStatus status){RiskEvent e=get(id);e.setStatus(status);return RiskEventResponse.from(repository.save(e));}private RiskEvent get(UUID id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Risk event not found: "+id));}private void apply(RiskEvent e,String title,RiskType type,ImpactLevel impact,String description,OffsetDateTime detected,UUID supplierId,UUID productId,UUID orderId,UUID shipmentId){e.setTitle(title);e.setRiskType(type);e.setImpactLevel(impact);e.setDescription(description);e.setDetectedAt(detected);e.setSupplier(supplierId==null?null:suppliers.findById(supplierId).orElseThrow(()->new ResourceNotFoundException("Supplier not found: "+supplierId)));e.setProduct(productId==null?null:products.findById(productId).orElseThrow(()->new ResourceNotFoundException("Product not found: "+productId)));e.setPurchaseOrder(orderId==null?null:orders.findById(orderId).orElseThrow(()->new ResourceNotFoundException("Purchase order not found: "+orderId)));e.setShipment(shipmentId==null?null:shipments.findById(shipmentId).orElseThrow(()->new ResourceNotFoundException("Shipment not found: "+shipmentId)));}}
